    type CommentDataSource = {
        update: (collection: string, id: string, payload: unknown) => Promise<unknown>;
    };

    const toggleReactionForFeedItems = (
        items: FeedItem[],
        itemId: string | number,
        emoji: string,
        dataSource: CommentDataSource | null | undefined,
        currentUserId: string | number,
    ): FeedItem[] => {
        let didChange = false;

        const nextItems = items.map(item => {
            if (item.id !== itemId) return item;

            didChange = true;
            const reactions = [...(item.reactions ?? [])];
            const idx = reactions.findIndex(r => r.emoji === emoji);

            if (idx >= 0) {
                const r = reactions[idx];
                if (r.reacted) {
                    if (r.count <= 1) {
                        reactions.splice(idx, 1);
                    } else {
                        reactions[idx] = { ...r, count: r.count - 1, reacted: false };
                    }
                } else {
                    reactions[idx] = { ...r, count: r.count + 1, reacted: true };
                }
            } else {
                reactions.push({ emoji, count: 1, reacted: true });
            }

            return { ...item, reactions };
        });

        if (didChange && dataSource) {
            dataSource
                .update('sys_comment', String(itemId), {
                    $toggleReaction: { emoji, userId: currentUserId },
                })
                .catch(() => {});
        }

        return nextItems;
    };

    const handleToggleReaction = useCallback(
        (itemId: string | number, emoji: string) => {
            setFeedItems(prev =>
                toggleReactionForFeedItems(prev, itemId, emoji, dataSource as CommentDataSource | null | undefined, currentUser.id),
            );
