    const createFeedItem = useCallback(
        (text: string, parentId?: string | number): FeedItem => ({
            id: crypto.randomUUID(),
            type: 'comment',
            actor: currentUser.name,
            actorAvatarUrl: 'avatar' in currentUser ? (currentUser as any).avatar : undefined,
            body: text,
            createdAt: new Date().toISOString(),
            ...(parentId != null ? { parentId } : {}),
        }),
        [currentUser],
    );

    const persistComment = useCallback(
        (newItem: FeedItem) => {
            if (!dataSource || !objectDef?.name || !recordId) return;
            const threadId = `${objectDef.name}:${recordId}`;
            dataSource
                .create('sys_comment', {
                    id: newItem.id,
                    threadId,
                    author: currentUser,
                    content: newItem.body,
                    mentions: [],
                    createdAt: newItem.createdAt,
                    ...(newItem.parentId != null ? { parentId: newItem.parentId } : {}),
                })
                .catch(() => {});
        },
        [currentUser, dataSource, objectDef?.name, recordId],
    );

    const handleAddComment = useCallback(
        async (text: string) => {
            const newItem = createFeedItem(text);
            setFeedItems(prev => [...prev, newItem]);
            persistComment(newItem);
